#!/usr/bin/env python3
"""news-image-20261121 entry: "The World in One Day — Saturday 21 November 2026".

A light "morning paper" magazine cover summing up the day's world news
in one 1024x1024 image. Seven stories, all reported on 21 November 2026:

1. Russian missiles fall in Poland as NATO jets scramble (hero) — two
   cruise missiles and a jet drone crash in Poland during Moscow's
   biggest air attack on Ukraine this year.
2. A 6.8 earthquake shakes Peru; Lima residents flee into the streets.
3. An Anthropic researcher says Claude proved the Riemann Hypothesis —
   maths' greatest riddle, claimed but unverified.
4. Wall Street slides into correction as the AI sell-off deepens.
5. COP31 misses its deadline in Antalya; the draft drops fossil fuels.
6. The UK and EU seal a post-Brexit reset deal.
7. Cyclone Akvan hits India's Odisha coast.

The image is embedded below (zlib-compressed, base64) and written out
verbatim. Standard library only, no network, fully deterministic: both
runs write byte-identical output.
"""
import base64
import os
import zlib

DATA = (
    "",
    "",
"",
"",
)


def main():
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")
    os.makedirs(out_dir, exist_ok=True)
    png = zlib.decompress(base64.b64decode("".join(DATA)))
    with open(os.path.join(out_dir, "entry.png"), "wb") as f:
        f.write(png)


if __name__ == "__main__":
    main()
